using System;

namespace SldFile.Binary.FeatureData;

internal sealed class Task11FeatureAuthoringTemplate
{
    internal Task11FeatureAuthoringTemplate(string sample, string featureName, string className, bool isRevolve, bool isCut, ushort streamVersion, int baseLength, ushort strippedFolderCount, string baseSha256, int markerOffset, uint markerValue, int blockLength, string blockBase64, int? endCondition, double? depth, double? draftAngle, bool? draftOutward, uint? fromType, double? fromOffsetDistance, bool? fromOffsetReverse, bool? isThinFeature, uint? thinWallType, double? wallThickness, bool? capEnds, bool? autoFilletCorners, double? autoFilletRadius, double? angle, int? axisType)
    {
        Sample=sample; FeatureName=featureName; ClassName=className; IsRevolve=isRevolve; IsCut=isCut; StreamVersion=streamVersion;
        BaseLength=baseLength; StrippedFolderCount=strippedFolderCount; BaseSha256=baseSha256; MarkerOffset=markerOffset; MarkerValue=markerValue;
        BlockLength=blockLength; Block=Convert.FromBase64String(blockBase64); EndCondition=endCondition; Depth=depth; DraftAngle=draftAngle; DraftOutward=draftOutward;
        FromType=fromType; FromOffsetDistance=fromOffsetDistance; FromOffsetReverse=fromOffsetReverse; IsThinFeature=isThinFeature; ThinWallType=thinWallType; WallThickness=wallThickness;
        CapEnds=capEnds; AutoFilletCorners=autoFilletCorners; AutoFilletRadius=autoFilletRadius; Angle=angle; AxisType=axisType;
    }
    internal string Sample { get; }
    internal string FeatureName { get; }
    internal string ClassName { get; }
    internal bool IsRevolve { get; }
    internal bool IsCut { get; }
    internal ushort StreamVersion { get; }
    internal int BaseLength { get; }
    internal ushort StrippedFolderCount { get; }
    internal string BaseSha256 { get; }
    internal int MarkerOffset { get; }
    internal uint MarkerValue { get; }
    internal int BlockLength { get; }
    internal byte[] Block { get; }
    internal int? EndCondition { get; }
    internal double? Depth { get; }
    internal double? DraftAngle { get; }
    internal bool? DraftOutward { get; }
    internal uint? FromType { get; }
    internal double? FromOffsetDistance { get; }
    internal bool? FromOffsetReverse { get; }
    internal bool? IsThinFeature { get; }
    internal uint? ThinWallType { get; }
    internal double? WallThickness { get; }
    internal bool? CapEnds { get; }
    internal bool? AutoFilletCorners { get; }
    internal double? AutoFilletRadius { get; }
    internal double? Angle { get; }
    internal int? AxisType { get; }
}

